-- Alta del proyecto "Arroyos de San Vicente" + carga inicial de sus 208 lotes,
-- importados desde el sistema SJ Desarrollo (estado y precio actuales).
--
-- El proyecto queda SIN PUBLICAR (publicado = false) hasta que se cargue el
-- masterplan interactivo (imagen + posición de cada lote) y se revisen los
-- datos. Mientras tanto es visible y editable desde /admin.
--
-- Mapeo de estados SJ Desarrollo -> Matu Lotes:
--   Disponible -> disponible
--   Vendido    -> vendido
--   Cerrado    -> no_disponible (espacios comunes / plaza / no están a la venta)
--
-- Superficie y dimensiones: se cargaron 20 x 30 m (600 m2) para los 208 lotes,
-- como valor estándar del proyecto. Si alguna manzana tiene medidas distintas,
-- se corrige después desde Admin > Lotes y precios (por lote o en lote).
--
-- Precio en USD: se tomó el valor cargado en SJ Desarrollo. Los lotes ya
-- vendidos que no tenían precio cargado ahí quedaron en 0 (no afecta nada,
-- porque no están a la venta).

values (
  'Arroyos de San Vicente',
  'arroyos-de-san-vicente',
  'Lotes con escritura garantizada en San Vicente, Buenos Aires.',
  'San Vicente, Buenos Aires',
  false,
  false,
  1
)
on conflict (slug) do nothing;

on conflict (proyecto_id, manzana, numero) do update set
  precio_usd = excluded.precio_usd,
  estado = excluded.estado,
  superficie_m2 = excluded.superficie_m2,
  dimensiones = excluded.dimensiones;
